import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64

.visible .entry the_entry_name(
    .param .u64 A_ptr,
    .param .u64 B_ptr,
    .param .u64 C_ptr,
    .param .u32 M,
    .param .u32 N,
    .param .u32 K,
    .param .u32 A_s0,
    .param .u32 A_s1,
    .param .u32 B_s0,
    .param .u32 B_s1,
    .param .u32 C_s0,
    .param .u32 C_s1
)
{
    .reg .pred %p<3>;
    .reg .b32 %r<40>;
    .reg .b64 %rd<20>;
    .reg .f32 %f<4>;

    // Load parameters
    ld.param.u64 %rd0, [A_ptr];
    ld.param.u64 %rd1, [B_ptr];
    ld.param.u64 %rd2, [C_ptr];
    ld.param.u32 %r0, [M];
    ld.param.u32 %r1, [N];
    ld.param.u32 %r2, [K];
    ld.param.u32 %r3, [A_s0];
    ld.param.u32 %r4, [A_s1];
    ld.param.u32 %r5, [B_s0];
    ld.param.u32 %r6, [B_s1];
    ld.param.u32 %r7, [C_s0];
    ld.param.u32 %r8, [C_s1];

    // Compute row/col indices
    mov.u32 %r9, %tid.x;
    mov.u32 %r10, %tid.y;
    mov.u32 %r11, %ctaid.x;
    mov.u32 %r12, %ctaid.y;
    mov.u32 %r13, %ntid.x;
    mov.u32 %r14, %ntid.y;

    mad.lo.u32 %r15, %r11, %r13, %r9;  // col
    mad.lo.u32 %r16, %r12, %r14, %r10; // row

    // Bounds check
    setp.ge.u32 %p0, %r16, %r0;
    @%p0 bra RET;
    setp.ge.u32 %p1, %r15, %r2;
    @%p1 bra RET;

    // Initialize accumulator
    mov.f32 %f0, 0f00000000;

    mov.u32 %r17, 0; // n iterator

LOOP:
    setp.ge.u32 %p2, %r17, %r1;
    @%p2 bra LOOP_END;

    // A[row * A_s0 + n * A_s1]
    mul.wide.u32 %rd3, %r16, %r3;
    mul.wide.u32 %rd4, %r17, %r4;
    add.s64 %rd5, %rd3, %rd4;
    shl.b64 %rd6, %rd5, 2;
    add.s64 %rd7, %rd0, %rd6;

    // B[n * B_s0 + col * B_s1]
    mul.wide.u32 %rd8, %r17, %r5;
    mul.wide.u32 %rd9, %r15, %r6;
    add.s64 %rd10, %rd8, %rd9;
    shl.b64 %rd11, %rd10, 2;
    add.s64 %rd12, %rd1, %rd11;

    // Load and accumulate
    ld.global.f32 %f1, [%rd7];
    ld.global.f32 %f2, [%rd12];
    fma.rn.f32 %f0, %f1, %f2, %f0;

    add.u32 %r17, %r17, 1;
    bra LOOP;

LOOP_END:
    // C[row * C_s0 + col * C_s1] = acc
    mul.wide.u32 %rd13, %r16, %r7;
    mul.wide.u32 %rd14, %r15, %r8;
    add.s64 %rd15, %rd13, %rd14;
    shl.b64 %rd16, %rd15, 2;
    add.s64 %rd17, %rd2, %rd16;

    st.global.f32 [%rd17], %f0;

RET:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("the_entry_name")

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, A, B):
        if not A.is_cuda or not B.is_cuda:
            raise RuntimeError("ModelNew requires CUDA tensors.")
        if A.dtype != torch.float32 or B.dtype != torch.float32:
            raise RuntimeError("ModelNew only supports float32 tensors.")
        if A.ndim != 2 or B.ndim != 2:
            raise RuntimeError("ModelNew expects 2D matrices.")
        M = int(A.size(0))
        N = int(A.size(1))
        if int(B.size(0)) != N:
            raise RuntimeError("Incompatible matrix shapes for matmul.")
        K = int(B.size(1))

        C = torch.empty(M, K, device=A.device, dtype=A.dtype)

        module = _get_ptx_module()

        block_x, block_y = 32, 32
        grid_x = (K + block_x - 1) // block_x
        grid_y = (M + block_y - 1) // block_y

        module.launch(
            "the_entry_name",
            grid=(grid_x, grid_y, 1),
            block=(block_x, block_y, 1),
            arguments=[
                A, B, C,
                i32(M), i32(N), i32(K),
                i32(A.stride(0)), i32(A.stride(1)),
                i32(B.stride(0)), i32(B.stride(1)),
                i32(C.stride(0)), i32(C.stride(1)),
            ],
            shared_memory=0,
            stream=torch.cuda.current_stream(A.device),
        )
        return C

